ValidationRule.errorConditionFormula:
AND(

/* Apply only to Customer Adjustment */
RecordType.DeveloperName = "Customer_Adjustment",

OR(

/* ================= Amount <= 250 & Approved ================= */
AND(
Credit_Request_Amount__c <= 250,
ISPICKVAL(Credit_Request_Status__c, "Approved"),
NOT(
OR(
$Profile.Name = "System Administrator",
Company_Lookup__r.Area_Sales_Director__c =
($User.FirstName & " " & $User.LastName)
)
)
),

/* ================= Amount > 250 & Submitted ================= */
AND(
Credit_Request_Amount__c > 250,
ISPICKVAL(Credit_Request_Status__c, "Submitted"),
NOT(
OR(
$Profile.Name = "System Administrator",
Company_Lookup__r.Area_Sales_Director__c =
($User.FirstName & " " & $User.LastName)
)
)
),

/* ================= Amount > 250 & Approved ================= */
AND(
Credit_Request_Amount__c > 250,
ISPICKVAL(Credit_Request_Status__c, "Approved"),
NOT(
OR(
$Profile.Name = "System Administrator",
Company_Lookup__r.Area_Sales_Director__c =
($User.FirstName & " " & $User.LastName)
)
)
),

/* ================= Amount > 250 & Denied ================= */
AND(
Credit_Request_Amount__c > 250,
ISPICKVAL(Credit_Request_Status__c, "Denied"),
NOT(
OR(
$Profile.Name = "System Administrator",
Company_Lookup__r.Area_Sales_Director__c =
($User.FirstName & " " & $User.LastName)
)
)
)

)
)
